/* 87-pocket-embed.js —— 掌机整页的内嵌副本（base64）。
   这块由 moon-pocket/tools/pack-pocket.mjs 生成，内容是一整张 pocket 页面；
   不要手改这里的 base64，要改就改 moon-pocket/index.html 然后重新打包。
   运行时装到 srcdoc 的 sandbox iframe（opaque origin）里跑，存档经 postMessage 交回宿主。 */
  // <MOON_POCKET_EMBED>
  const MOON_POCKET_EMBED_B64 = '';
  // </MOON_POCKET_EMBED>
  let _pocketHtmlCache = null;
  function pocketEmbedHtml() {
    if (_pocketHtmlCache !== null) return _pocketHtmlCache;
    if (!MOON_POCKET_EMBED_B64) { _pocketHtmlCache = ''; return ''; }
    try {
      const bin = atob(MOON_POCKET_EMBED_B64);
      const bytes = new Uint8Array(bin.length);
      for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
      _pocketHtmlCache = new TextDecoder('utf-8').decode(bytes);
    } catch (e) { _pocketHtmlCache = ''; }
    return _pocketHtmlCache;
  }
